/**
 * Modeled loosely on the shape the real Berkeleytime datapuller receives from
 * campus SIS (Student Information System) when it pulls course data. See
 * apps/datapuller/src/lib/courses.ts in the main repo for the real thing.
 *
 * A few real-world facts that matter for this exercise:
 *
 *  - `courseId` is SIS's *stable* internal identifier for a course. It does
 *    NOT change when a course is renumbered or moves departments.
 *  - `subject` + `number` is the human-facing course number (e.g. "COMPSCI 61A").
 *    This CAN change between versions of the same `courseId` (e.g. a course
 *    being renumbered next term).
 *  - `status` is "ACTIVE" (currently in effect) or "FUTURE" (scheduled to take
 *    effect on `fromDate`, but not in effect yet). SIS can return both an
 *    ACTIVE and a FUTURE record for the same course in the same pull.
 *  - `fromDate` is the date this version of the course record takes/took effect.
 *
 * SIS is a periodic, full-snapshot feed: every pull returns the current set of
 * ACTIVE/FUTURE records, and the datapuller upserts them into Berkeleytime's
 * database. There is no "diff" from the previous pull -- each run must decide
 * independently, from scratch, which record is canonical.
 */
export type CourseStatus = "ACTIVE" | "FUTURE";

export interface RawCourseVersion {
  /** Stable SIS identifier. Shared by ACTIVE/FUTURE versions of the same course. */
  courseId: string;
  /** e.g. "COMPSCI" */
  subject: string;
  /** e.g. "61A" */
  number: string;
  status: CourseStatus;
  title: string;
  /** ISO date string (YYYY-MM-DD): when this version takes/took effect. */
  fromDate: string;
}
